import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  fmtNum,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 1200;
const CX = W / 2;

const COLORS = {
  encoder: { fill: '#e8f5e9', stroke: '#4caf50' },
  decoder: { fill: '#e3f2fd', stroke: '#1976d2' },
  seq2seq: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  weight:  { fill: '#f1f5f9', stroke: '#64748b' },
  loss:    { fill: '#fff3e0', stroke: '#e65100' },
  text:    'var(--text)' as string,
  muted:   'var(--text-muted)' as string,
};

// — Layout constants (generous spacing to prevent overlap) —
const COL_W = 340;
const COL_GAP = 40;
const COL_START_X = (W - 3 * COL_W - 2 * COL_GAP) / 2;
const COL_CX = [
  COL_START_X + COL_W / 2,
  COL_START_X + COL_W + COL_GAP + COL_W / 2,
  COL_START_X + 2 * (COL_W + COL_GAP) + COL_W / 2,
];

const BOX_H = 60;
const MAT_H = 80;
const VEC_H = 42;
const VEC_W = 150;
const WEIGHT_W = 135;
const WEIGHT_H = 92;
const SM_W = 84;
const SM_H = 68;
const SEQ_W = 190;
const GROUP_GAP = 80;
const BOX_TO_ROW = 60;
const ROW_EQ = 42;
const COL_HDR_H = 56;
const GRID_SZ = 60;

interface ArchParams { dModel: number; seqLen: number; dFf: number; variant: string; }
interface ArchStep extends StepInfo {}

const ARCHS = [
  { name: 'Encoder-only', model: 'BERT / RoBERTa', task: 'Classification / NER', mask: 'full' as const, maskLabel: 'Full attention', color: COLORS.encoder },
  { name: 'Decoder-only', model: 'GPT / Llama', task: 'Generation / Chat', mask: 'causal' as const, maskLabel: 'Causal mask', color: COLORS.decoder },
  { name: 'Encoder-Decoder', model: 'T5 / BART', task: 'Translation / Summar.', mask: 'cross' as const, maskLabel: 'Cross-attention', color: COLORS.seq2seq },
];

// ═══════════════════════════════════════════════════════════════════════════════
// Low-level helpers
// ═══════════════════════════════════════════════════════════════════════════════

function lbl(g: Gsel, x: number, y: number, text: string, opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}): void {
  drawLabel(g as Sel, x, y, text, opts);
}
function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void { drawArrow(g as Sel, x, y1, x, y2, { color }); }
function startGroup(g: Gsel, cls: string, step: number): Gsel { return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step)); }

function stepHeader(g: Gsel, cx: number, y: number, sn: number, title: string, formula: string, fill: string, stroke: string, width = COL_W - 10): number {
  const w = width;
  g.append('rect').attr('x', cx - w/2).attr('y', y).attr('width', w).attr('height', BOX_H).attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w/2 + 20).attr('cy', y + BOX_H/2).attr('r', 13).attr('fill', stroke);
  lbl(g, cx - w/2 + 20, y + BOX_H/2 + 1, String(sn), { size: 12, weight: '700', color: '#fff' });
  lbl(g, cx - w/2 + 40, y + BOX_H/2 - 2, title, { size: 11, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx + w/2 - 10, y + BOX_H/2 - 2, formula, { size: 8, color: 'var(--text-muted)', font: 'monospace', anchor: 'end' });
  return y + BOX_H;
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 16).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 14, weight: '700', color });
}

function drawShapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.8 + 24, 150);
  const h = 26;
  g.append('rect').attr('x', cx - w/2).attr('y', cy - h/2).attr('width', w).attr('height', h).attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy, text, { size: 8.5, color, font: 'monospace' });
}

function drawBadge(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string): void {
  const bw = Math.max(80, text.length * 7.5 + 16);
  const bh = 32;
  g.append('rect').attr('x', cx - bw/2).attr('y', cy - bh/2).attr('width', bw).attr('height', bh).attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 10, weight: '600', color: stroke });
}

function drawColHeader(g: Gsel, cx: number, y: number, name: string, model: string, task: string, color: { fill: string; stroke: string }): number {
  g.append('rect').attr('x', cx - COL_W/2).attr('y', y).attr('width', COL_W).attr('height', COL_HDR_H).attr('rx', 8).attr('fill', color.fill).attr('stroke', color.stroke).attr('stroke-width', 1.5);
  lbl(g, cx, y + 16, name, { size: 13, weight: '700', color: color.stroke });
  lbl(g, cx, y + 30, model, { size: 9, font: 'monospace', color: '#666' });
  if (task) lbl(g, cx, y + 44, task, { size: 8.5, color: '#999' });
  return y + COL_HDR_H;
}

function drawParamSummary(g: Gsel, cx: number, y: number, p: ArchParams): number {
  const items = [`d_model=${p.dModel}`, `seq_len=${p.seqLen}`, `d_ff=${p.dFf}`, `variant: ${p.variant}`];
  const w = W - 160; const h = 32;
  g.append('rect').attr('x', cx - w/2).attr('y', y).attr('width', w).attr('height', h).attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => { lbl(g, cx - w/2 + segW * (i + 0.5), y + h/2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' }); });
  return y + h;
}

function drawSeqMatrix(g: Gsel, cx: number, cy: number, label: string, sub: string, fill: string, stroke: string): void {
  drawMatrixBlock(g as Sel, cx - SEQ_W/2, cy - MAT_H/2, { width: SEQ_W, height: MAT_H, label, sublabel: sub, fill, stroke, cols: 8, rows: 5, dimTop: 'S', dimRight: 'D' });
}
function drawWeight(g: Gsel, cx: number, cy: number, label: string, sub: string, fill = COLORS.weight.fill, stroke = COLORS.weight.stroke, w = WEIGHT_W, h = WEIGHT_H): void {
  drawMatrixBlock(g as Sel, cx - w/2, cy - h/2, { width: w, height: h, label, sublabel: sub, fill, stroke, cols: 5, rows: 5 });
}
function drawSmWeight(g: Gsel, cx: number, cy: number, label: string, sub: string, fill = COLORS.weight.fill, stroke = COLORS.weight.stroke): void {
  drawMatrixBlock(g as Sel, cx - SM_W/2, cy - SM_H/2, { width: SM_W, height: SM_H, label, sublabel: sub, fill, stroke, cols: 4, rows: 4 });
}
function drawSmVec(g: Gsel, cx: number, cy: number, label: string, sub: string, fill: string, stroke: string, w = VEC_W): void {
  drawMatrixBlock(g as Sel, cx - w/2, cy - VEC_H/2, { width: w, height: VEC_H, label, sublabel: sub, fill, stroke, cols: 8, rows: 1 });
}

function drawMaskGrid(g: Gsel, cx: number, cy: number, maskType: 'full' | 'causal' | 'cross', color: string, sz = GRID_SZ): void {
  const n = 6; const cs = sz / n;
  const gg = g.append('g').attr('transform', `translate(${cx - sz/2}, ${cy - sz/2})`);
  for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) {
    const vis = maskType === 'full' ? true : maskType === 'causal' ? c <= r : true;
    gg.append('rect').attr('x', c*cs).attr('y', r*cs).attr('width', cs-1).attr('height', cs-1).attr('rx', 1).attr('fill', vis ? color : '#f5f5f5').attr('opacity', vis ? 0.5 : 0.12).attr('stroke', color).attr('stroke-width', 0.3);
  }
  if (maskType === 'cross') for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) gg.append('circle').attr('cx', c*cs+cs/2).attr('cy', r*cs+cs/2).attr('r', 1.5).attr('fill', color).attr('opacity', 0.55);
}

function drawScoreGrid(g: Gsel, cx: number, cy: number, maskType: 'full' | 'causal' | 'cross', color: string, sz = GRID_SZ): void {
  const n = 6; const cs = sz / n;
  const gg = g.append('g').attr('transform', `translate(${cx - sz/2}, ${cy - sz/2})`);
  let seed = 42;
  const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
  for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) {
    const vis = maskType === 'full' ? true : maskType === 'causal' ? c <= r : true;
    const v = lcg();
    gg.append('rect').attr('x', c*cs).attr('y', r*cs).attr('width', cs-1).attr('height', cs-1).attr('rx', 1).attr('fill', color).attr('opacity', vis ? 0.15 + v*0.5 : 0.05).attr('stroke', color).attr('stroke-width', 0.3);
  }
}

function drawCompTable(g: Gsel, cx: number, y: number, rows: string[][], colColors: string[]): number {
  const rowH = 24; const colWidths = [130, 170, 170, 170]; const totalW = colWidths.reduce((a,b)=>a+b,0); const tblX = cx - totalW/2;
  rows.forEach((row, ri) => {
    let rx = tblX;
    row.forEach((cell, ci) => {
      const cw = colWidths[ci];
      g.append('rect').attr('x', rx).attr('y', y).attr('width', cw).attr('height', rowH).attr('rx', ri===0?4:0).attr('fill', ri===0?'#f5f5f5':ri%2===0?'#fafafa':'#fff').attr('stroke', '#e0e0e0').attr('stroke-width', 0.5);
      lbl(g, rx + 10, y + rowH/2, cell, { size: 9.5, weight: ri===0||ci===0?'700':'400', color: ri===0?colColors[ci]:ci===0?'#555':'#333', anchor: 'start' });
      rx += cw;
    });
    y += rowH;
  });
  return y;
}

function makeStep(id: number, sl: string, l: string, f: string, ex: string, sg: string, c: string, fl: string, cl?: string[]): ArchStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex, code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

function forkArrows(g: Gsel, forkY: number): void {
  ARCHS.forEach((_, ci) => { drawArrow(g as Sel, CX, forkY - 12, COL_CX[ci], forkY + 12, { color: '#78909c' }); });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Overview variant — row-based rendering
// ═══════════════════════════════════════════════════════════════════════════════

function renderOverview(g: Gsel, startY: number, p: ArchParams): { steps: ArchStep[]; y: number } {
  const steps: ArchStep[] = [];
  let stepId = 1;
  let y = startY;

  // Step 1: Shared input
  const grpIn = startGroup(g, 'step-arch-input', stepId);
  drawSeqMatrix(grpIn, CX, y, 'tokens', `[B, ${p.seqLen}, ${p.dModel}]`, COLORS.encoder.fill, COLORS.encoder.stroke);
  lbl(grpIn, CX, y + MAT_H/2 + 18, 'shared input tokens', { size: 9.5, color: COLORS.muted });
  steps.push(makeStep(stepId, 'Input', 'Input Tokens', `tokens: [B, S, D]`, 'Shared input token embeddings fed to all three architectures.', 'step-arch-input', COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++; y += MAT_H/2 + 48;

  // Fork arrows + column headers
  forkArrows(g, y); y += 24;
  ARCHS.forEach((a, ci) => drawColHeader(g, COL_CX[ci], y, a.name, a.model, a.task, a.color));
  y += COL_HDR_H + 16;

  const colY = [y, y, y];

  // ── Step 2: Embed + Pos (rendered across all 3 columns) ──
  ARCHS.forEach((arch, ci) => {
    const cx = COL_CX[ci]; const c = arch.color;
    const grp = startGroup(g, 'step-arch-embed', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'Embed + Pos', 'x = emb + pos', c.fill, c.stroke);
    const wY = hBot + BOX_TO_ROW + WEIGHT_H/2;
    drawWeight(grp, cx, wY, 'W_emb', `[V, ${p.dModel}]`);
    arrowDown(grp, cx, hBot, wY - WEIGHT_H/2, c.stroke);
    const eY = wY + WEIGHT_H/2 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, eY, 'x', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, wY + WEIGHT_H/2, eY - MAT_H/2, c.stroke);
    drawShapeEq(grp, cx, eY + MAT_H/2 + 20, `tok·W_emb [V,${p.dModel}] + pos → x [${p.seqLen},${p.dModel}]`, c.stroke);
    colY[ci] = eY + MAT_H/2 + 40;
  });
  steps.push(makeStep(stepId, 'Embed', 'Embedding + Positional Encoding', 'x = tok_emb + pos_emb', 'Token embeddings + positional encodings applied independently per architecture.', 'step-arch-embed', COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 3: QKV Projection ──
  ARCHS.forEach((arch, ci) => {
    const cx = COL_CX[ci]; const c = arch.color;
    const grp = startGroup(g, 'step-arch-qkv', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'QKV Projection', 'Q,K,V = x·W', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const qkvY = hBot + BOX_TO_ROW + SM_H/2;
    const qGap = SM_W + 14; const qXs = [cx - qGap, cx, cx + qGap];
    ['W_q', 'W_k', 'W_v'].forEach((ql, qi) => drawSmWeight(grp, qXs[qi], qkvY, ql, `[${p.dModel},${p.dModel}]`));
    arrowDown(grp, cx, hBot, qkvY - SM_H/2, c.stroke);
    const qoY = qkvY + SM_H/2 + ROW_EQ + VEC_H/2;
    ['Q', 'K', 'V'].forEach((ql, qi) => {
      drawSmVec(grp, qXs[qi], qoY, ql, `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke, 82);
      arrowDown(grp, qXs[qi], qkvY + SM_H/2, qoY - VEC_H/2, c.stroke);
    });
    colY[ci] = qoY + VEC_H/2 + 24;
  });
  steps.push(makeStep(stepId, 'QKV', 'QKV Projection', 'Q=xW_q, K=xW_k, V=xW_v', 'Linear projections of input to query, key, value matrices.', 'step-arch-qkv', COLORS.decoder.stroke, COLORS.decoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 4: Attention Scores + Mask ──
  ARCHS.forEach((arch, ci) => {
    const cx = COL_CX[ci]; const c = arch.color;
    const grp = startGroup(g, 'step-arch-scores', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'Scores + Mask', 'QK^T/√d → mask', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    // Score grid and mask grid side by side
    const gridY = hBot + BOX_TO_ROW + GRID_SZ/2;
    drawScoreGrid(grp, cx - GRID_SZ/2 - 8, gridY, arch.mask, c.stroke, GRID_SZ);
    drawMaskGrid(grp, cx + GRID_SZ/2 + 8, gridY, arch.mask, c.stroke, GRID_SZ);
    lbl(grp, cx - GRID_SZ/2 - 8, gridY + GRID_SZ/2 + 12, 'scores', { size: 8, color: COLORS.muted });
    lbl(grp, cx + GRID_SZ/2 + 8, gridY + GRID_SZ/2 + 12, arch.maskLabel, { size: 8, color: COLORS.muted });
    drawShapeEq(grp, cx, gridY + GRID_SZ/2 + 28, `Q·K^T/√d → scores [${p.seqLen},${p.seqLen}]`, c.stroke);
    colY[ci] = gridY + GRID_SZ/2 + 48;
  });
  steps.push(makeStep(stepId, 'Scores', 'Attention Scores + Mask', 'scores = Q·K^T/√d, apply mask', 'Dot-product attention scores with architecture-specific masking.', 'step-arch-scores', COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 5: Softmax + Output Projection ──
  ARCHS.forEach((arch, ci) => {
    const cx = COL_CX[ci]; const c = arch.color;
    const grp = startGroup(g, 'step-arch-attn-out', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'Softmax + Out', 'softmax(s)·V·W_o', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const smY = hBot + BOX_TO_ROW + 16;
    drawBadge(grp, cx, smY, 'softmax', c.fill, c.stroke);
    arrowDown(grp, cx, hBot, smY - 16, c.stroke);
    const woY = smY + 16 + ROW_EQ + WEIGHT_H/2;
    drawWeight(grp, cx, woY, 'W_o', `[${p.dModel},${p.dModel}]`);
    arrowDown(grp, cx, smY + 16, woY - WEIGHT_H/2, c.stroke);
    const aoY = woY + WEIGHT_H/2 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, aoY, 'attn_out', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, woY + WEIGHT_H/2, aoY - MAT_H/2, c.stroke);
    drawShapeEq(grp, cx, aoY + MAT_H/2 + 20, `softmax(scores)·V → W_o → [${p.seqLen},${p.dModel}]`, c.stroke);
    colY[ci] = aoY + MAT_H/2 + 40;
  });
  steps.push(makeStep(stepId, 'AttnOut', 'Softmax + Output Projection', 'out = softmax(scores)·V·W_o', 'Softmax over masked scores, weighted sum of V, output projection.', 'step-arch-attn-out', COLORS.decoder.stroke, COLORS.decoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 6: Residual + Norm 1 ──
  ARCHS.forEach((arch, ci) => {
    const cx = COL_CX[ci]; const c = arch.color;
    const grp = startGroup(g, 'step-arch-rn1', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'Add & Norm', 'LN(x + attn)', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const addY = hBot + BOX_TO_ROW + 16;
    opCircle(grp, cx, addY, '⊕', c.stroke);
    lbl(grp, cx + 22, addY, 'residual', { size: 8.5, color: COLORS.muted, anchor: 'start' });
    arrowDown(grp, cx, hBot, addY - 16, c.stroke);
    const lnY = addY + 16 + ROW_EQ/2 + 16;
    drawBadge(grp, cx, lnY, 'LayerNorm', c.fill, c.stroke);
    arrowDown(grp, cx, addY + 16, lnY - 16, c.stroke);
    const r1Y = lnY + 16 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, r1Y, 'x_n1', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, lnY + 16, r1Y - MAT_H/2, c.stroke);
    colY[ci] = r1Y + MAT_H/2 + 28;
  });
  steps.push(makeStep(stepId, 'ResNorm1', 'Residual + LayerNorm', 'x = LN(x + attn(x))', 'Residual connection around attention + layer normalization.', 'step-arch-rn1', COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 7: FFN Up + Activation ──
  ARCHS.forEach((arch, ci) => {
    const cx = COL_CX[ci]; const c = arch.color;
    const grp = startGroup(g, 'step-arch-ffn-up', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'FFN Up', 'up = x·W_up', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const wuY = hBot + BOX_TO_ROW + WEIGHT_H/2;
    drawWeight(grp, cx, wuY, 'W_up', `[${p.dModel},${p.dFf}]`);
    arrowDown(grp, cx, hBot, wuY - WEIGHT_H/2, c.stroke);
    const actY = wuY + WEIGHT_H/2 + ROW_EQ/2 + 16;
    drawBadge(grp, cx, actY, 'GELU', c.fill, c.stroke);
    arrowDown(grp, cx, wuY + WEIGHT_H/2, actY - 16, c.stroke);
    const uoY = actY + 16 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, uoY, 'h', `[${p.seqLen},${p.dFf}]`, c.fill, c.stroke);
    arrowDown(grp, cx, actY + 16, uoY - MAT_H/2, c.stroke);
    drawShapeEq(grp, cx, uoY + MAT_H/2 + 20, `x·W_up [${p.dModel},${p.dFf}] → GELU → h [${p.seqLen},${p.dFf}]`, c.stroke);
    colY[ci] = uoY + MAT_H/2 + 40;
  });
  steps.push(makeStep(stepId, 'FFNUp', 'FFN Up-Projection + Activation', 'h = GELU(x · W_up)', 'Up-project to d_ff then apply GELU activation.', 'step-arch-ffn-up', COLORS.seq2seq.stroke, COLORS.seq2seq.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 8: FFN Down ──
  ARCHS.forEach((arch, ci) => {
    const cx = COL_CX[ci]; const c = arch.color;
    const grp = startGroup(g, 'step-arch-ffn-dn', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'FFN Down', 'out = h·W_dn', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const wdY = hBot + BOX_TO_ROW + WEIGHT_H/2;
    drawWeight(grp, cx, wdY, 'W_down', `[${p.dFf},${p.dModel}]`);
    arrowDown(grp, cx, hBot, wdY - WEIGHT_H/2, c.stroke);
    const foY = wdY + WEIGHT_H/2 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, foY, 'ffn_out', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, wdY + WEIGHT_H/2, foY - MAT_H/2, c.stroke);
    drawShapeEq(grp, cx, foY + MAT_H/2 + 20, `h·W_down [${p.dFf},${p.dModel}] → ffn_out [${p.seqLen},${p.dModel}]`, c.stroke);
    colY[ci] = foY + MAT_H/2 + 40;
  });
  steps.push(makeStep(stepId, 'FFNDn', 'FFN Down-Projection', 'out = h · W_down', 'Down-project back to d_model.', 'step-arch-ffn-dn', COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 9: Residual + Norm 2 ──
  ARCHS.forEach((arch, ci) => {
    const cx = COL_CX[ci]; const c = arch.color;
    const grp = startGroup(g, 'step-arch-rn2', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'Add & Norm', 'LN(x + ffn)', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const a2Y = hBot + BOX_TO_ROW + 16;
    opCircle(grp, cx, a2Y, '⊕', c.stroke);
    lbl(grp, cx + 22, a2Y, 'residual', { size: 8.5, color: COLORS.muted, anchor: 'start' });
    arrowDown(grp, cx, hBot, a2Y - 16, c.stroke);
    const ln2Y = a2Y + 16 + ROW_EQ/2 + 16;
    drawBadge(grp, cx, ln2Y, 'LayerNorm', c.fill, c.stroke);
    arrowDown(grp, cx, a2Y + 16, ln2Y - 16, c.stroke);
    const r2Y = ln2Y + 16 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, r2Y, 'x_n2', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, ln2Y + 16, r2Y - MAT_H/2, c.stroke);
    colY[ci] = r2Y + MAT_H/2 + 28;
  });
  steps.push(makeStep(stepId, 'ResNorm2', 'Residual + LayerNorm', 'x = LN(x + ffn(x))', 'Second residual connection + layer normalization.', 'step-arch-rn2', COLORS.decoder.stroke, COLORS.decoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 10: N layers + Output ──
  ARCHS.forEach((arch, ci) => {
    const cx = COL_CX[ci]; const c = arch.color;
    const grp = startGroup(g, 'step-arch-nl', stepId);
    const nlY = colY[ci] + 8;
    drawBadge(grp, cx, nlY, '× N layers', c.fill, c.stroke);
    const coY = nlY + 24 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, coY, 'output', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, nlY + 24, coY - MAT_H/2, c.stroke);
    lbl(grp, cx, coY + MAT_H/2 + 14, arch.task.toLowerCase(), { size: 9, color: COLORS.muted });
    colY[ci] = coY + MAT_H/2 + 24;
  });
  steps.push(makeStep(stepId, 'NLayers', 'Stacked Layers + Output', 'output = block^N(x)', 'Transformer block repeated N times, producing final representations.', 'step-arch-nl', COLORS.seq2seq.stroke, COLORS.seq2seq.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;

  // Converge arrows
  ARCHS.forEach((_, ci) => drawArrow(g as Sel, COL_CX[ci], y - GROUP_GAP, CX, y, { color: '#78909c' }));

  // ── Step 11: Shared output ──
  const gOut = startGroup(g, 'step-arch-out', stepId);
  drawSeqMatrix(gOut, CX, y, 'logits', `[B,${p.seqLen},${p.dModel}]`, COLORS.seq2seq.fill, COLORS.seq2seq.stroke);
  lbl(gOut, CX, y + MAT_H/2 + 18, 'task-dependent output', { size: 9.5, color: COLORS.muted });
  steps.push(makeStep(stepId, 'Output', 'Output Representations', `output: [B, S, D]`, 'Final representations for downstream tasks.', 'step-arch-out', COLORS.seq2seq.stroke, COLORS.seq2seq.fill));
  y += MAT_H/2 + 44;

  y = drawCompTable(g, CX, y,
    [['Property','Encoder-only','Decoder-only','Encoder-Decoder'],
     ['Attention','Bidirectional','Causal (masked)','Cross + Causal'],
     ['Pre-training','MLM','Next-token predict','Span corruption'],
     ['Fine-tuning','Classification','Instruct / chat','Seq2seq task'],
     ['Scaling winner','Understanding','Unified + generative','Translation'],
     ['Examples','BERT, RoBERTa','GPT, Llama','T5, BART']],
    ['#666', COLORS.encoder.stroke, COLORS.decoder.stroke, COLORS.seq2seq.stroke]) + 24;

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Attention variant — row-based rendering
// ═══════════════════════════════════════════════════════════════════════════════

function renderAttention(g: Gsel, startY: number, p: ArchParams): { steps: ArchStep[]; y: number } {
  const steps: ArchStep[] = [];
  let stepId = 1;
  let y = startY;
  const types = [
    { name: 'Self-Attention', desc: 'Q=K=V=X', mask: 'full' as const, color: COLORS.encoder },
    { name: 'Cross-Attention', desc: 'Q=dec, K=V=enc', mask: 'full' as const, color: COLORS.decoder },
    { name: 'Causal Attention', desc: 'Q=K=V=X, masked', mask: 'causal' as const, color: COLORS.seq2seq },
  ];

  // Step 1: Shared input
  const gIn = startGroup(g, 'step-attn-input', stepId);
  drawSeqMatrix(gIn, CX, y, 'X', `[${p.seqLen},${p.dModel}]`, COLORS.encoder.fill, COLORS.encoder.stroke);
  lbl(gIn, CX, y + MAT_H/2 + 18, 'shared input', { size: 9.5, color: COLORS.muted });
  steps.push(makeStep(stepId, 'Input', 'Input Hidden States', `X: [${p.seqLen}, ${p.dModel}]`, 'Shared input for QKV projection.', 'step-attn-input', COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++; y += MAT_H/2 + 48;

  forkArrows(g, y); y += 24;
  types.forEach((t, ci) => drawColHeader(g, COL_CX[ci], y, t.name, t.desc, '', t.color));
  y += COL_HDR_H + 16;

  const colY = [y, y, y];

  // ── Step 2: QKV Projection ──
  types.forEach((t, ci) => {
    const cx = COL_CX[ci]; const c = t.color;
    const grp = startGroup(g, 'step-attn-qkv', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'QKV Projection', 'Q,K,V = X·W', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const qkvY = hBot + BOX_TO_ROW + SM_H/2;
    const qGap = SM_W + 14; const qXs = [cx - qGap, cx, cx + qGap];
    ['W_q', 'W_k', 'W_v'].forEach((ql, qi) => drawSmWeight(grp, qXs[qi], qkvY, ql, `[${p.dModel},${p.dModel}]`));
    arrowDown(grp, cx, hBot, qkvY - SM_H/2, c.stroke);
    lbl(grp, cx, qkvY + SM_H/2 + 12, 'project to Q, K, V', { size: 8.5, color: COLORS.muted });
    const qoY = qkvY + SM_H/2 + ROW_EQ + VEC_H/2;
    ['Q', 'K', 'V'].forEach((ql, qi) => {
      drawSmVec(grp, qXs[qi], qoY, ql, `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke, 82);
      arrowDown(grp, qXs[qi], qkvY + SM_H/2, qoY - VEC_H/2, c.stroke);
    });
    colY[ci] = qoY + VEC_H/2 + 26;
  });
  steps.push(makeStep(stepId, 'QKV', 'QKV Projection', 'Q=XW_q, K=XW_k, V=XW_v', 'Linear projections of input to Q, K, V matrices.', 'step-attn-qkv', COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 3: Score Computation ──
  types.forEach((t, ci) => {
    const cx = COL_CX[ci]; const c = t.color;
    const grp = startGroup(g, 'step-attn-sc', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'Scores', 'Q·K^T/√d', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const scY = hBot + BOX_TO_ROW + GRID_SZ/2;
    drawScoreGrid(grp, cx, scY, t.mask, c.stroke);
    lbl(grp, cx, scY + GRID_SZ/2 + 12, `scores [${p.seqLen},${p.seqLen}]`, { size: 8.5, color: COLORS.muted, font: 'monospace' });
    drawShapeEq(grp, cx, scY + GRID_SZ/2 + 28, `Q [${p.seqLen},${p.dModel}]·K^T [${p.dModel},${p.seqLen}]/√d → [${p.seqLen},${p.seqLen}]`, c.stroke);
    colY[ci] = scY + GRID_SZ/2 + 48;
  });
  steps.push(makeStep(stepId, 'Scores', 'Score Computation', 'scores = Q·K^T/√d_k', 'Dot-product scores scaled by 1/√d_k.', 'step-attn-sc', COLORS.decoder.stroke, COLORS.decoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 4: Mask Application ──
  types.forEach((t, ci) => {
    const cx = COL_CX[ci]; const c = t.color;
    const grp = startGroup(g, 'step-attn-mk', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'Mask', t.mask === 'causal' ? 'causal' : 'none', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const mkY = hBot + BOX_TO_ROW + GRID_SZ/2;
    drawMaskGrid(grp, cx, mkY, t.mask, c.stroke);
    lbl(grp, cx, mkY + GRID_SZ/2 + 12, t.mask === 'causal' ? 'lower-triangular' : 'all visible', { size: 8.5, color: COLORS.muted });
    colY[ci] = mkY + GRID_SZ/2 + 28;
  });
  steps.push(makeStep(stepId, 'Mask', 'Mask Application', 'mask: full / causal', 'Apply architecture-specific attention mask.', 'step-attn-mk', COLORS.seq2seq.stroke, COLORS.seq2seq.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 5: Softmax ──
  types.forEach((t, ci) => {
    const cx = COL_CX[ci]; const c = t.color;
    const grp = startGroup(g, 'step-attn-sm', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'Softmax', 'weights=softmax(s)', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const smY = hBot + BOX_TO_ROW + 16;
    drawBadge(grp, cx, smY, 'softmax', c.fill, c.stroke);
    arrowDown(grp, cx, hBot, smY - 16, c.stroke);
    const wY = smY + 16 + ROW_EQ + VEC_H/2;
    drawSmVec(grp, cx, wY, 'weights', `[${p.seqLen},${p.seqLen}]`, c.fill, c.stroke, 150);
    arrowDown(grp, cx, smY + 16, wY - VEC_H/2, c.stroke);
    colY[ci] = wY + VEC_H/2 + 26;
  });
  steps.push(makeStep(stepId, 'Softmax', 'Softmax', 'weights = softmax(scores)', 'Normalize scores to attention weights.', 'step-attn-sm', COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 6: Weighted Sum (Output) ──
  types.forEach((t, ci) => {
    const cx = COL_CX[ci]; const c = t.color;
    const grp = startGroup(g, 'step-attn-out', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'Output', 'out = w·V', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const oY = hBot + BOX_TO_ROW + MAT_H/2;
    drawSeqMatrix(grp, cx, oY, 'attn_out', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, hBot, oY - MAT_H/2, c.stroke);
    drawShapeEq(grp, cx, oY + MAT_H/2 + 20, `weights [${p.seqLen},${p.seqLen}]·V [${p.seqLen},${p.dModel}] → [${p.seqLen},${p.dModel}]`, c.stroke);
    colY[ci] = oY + MAT_H/2 + 40;
  });
  steps.push(makeStep(stepId, 'Output', 'Weighted Sum', 'out = weights @ V', 'Weighted combination of values using attention weights.', 'step-attn-out', COLORS.decoder.stroke, COLORS.decoder.fill));
  y = Math.max(...colY) + GROUP_GAP;

  y = drawCompTable(g, CX, y,
    [['Property','Self-Attention','Cross-Attention','Causal Attention'],
     ['Q source','Same input','Decoder','Same input'],
     ['K,V source','Same input','Encoder','Same input'],
     ['Mask','None (full)','None (full)','Causal (lower-tri)'],
     ['Use case','Encoding','Seq2Seq decode','Autoregressive gen'],
     ['Example','BERT','T5 decoder','GPT, Llama']],
    ['#666', COLORS.encoder.stroke, COLORS.decoder.stroke, COLORS.seq2seq.stroke]) + 24;

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// FFN/MoE variant — row-based rendering
// ═══════════════════════════════════════════════════════════════════════════════

function renderFfnMoe(g: Gsel, startY: number, p: ArchParams): { steps: ArchStep[]; y: number } {
  const steps: ArchStep[] = [];
  let stepId = 1;
  let y = startY;
  const types = [
    { name: 'Dense FFN', model: 'Standard Transformer', color: COLORS.encoder },
    { name: 'MoE FFN', model: 'Mixtral / DeepSeek', color: COLORS.decoder },
    { name: 'Seq2Seq FFN', model: 'T5 / BART', color: COLORS.seq2seq },
  ];

  // Step 1: Shared input
  const gIn = startGroup(g, 'step-ffn-in', stepId);
  drawSeqMatrix(gIn, CX, y, 'x', `[${p.seqLen},${p.dModel}]`, COLORS.encoder.fill, COLORS.encoder.stroke);
  lbl(gIn, CX, y + MAT_H/2 + 18, 'shared input', { size: 9.5, color: COLORS.muted });
  steps.push(makeStep(stepId, 'Input', 'Input', `x: [${p.seqLen}, ${p.dModel}]`, 'Shared input for all FFN variants.', 'step-ffn-in', COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++; y += MAT_H/2 + 48;

  forkArrows(g, y); y += 24;
  types.forEach((t, ci) => drawColHeader(g, COL_CX[ci], y, t.name, t.model, '', t.color));
  y += COL_HDR_H + 16;

  const colY = [y, y, y];

  // ── Step 2: Up Projection / Router ──
  // Dense & Seq2Seq: W_up; MoE: W_router
  // Dense FFN (col 0)
  {
    const cx = COL_CX[0]; const c = COLORS.encoder;
    const grp = startGroup(g, 'step-ffn-up', stepId);
    const hBot = stepHeader(grp, cx, colY[0], stepId, 'Up Projection', 'up = x·W_up', c.fill, c.stroke);
    arrowDown(grp, cx, colY[0], hBot, c.stroke);
    const wuY = hBot + BOX_TO_ROW + WEIGHT_H/2;
    drawWeight(grp, cx, wuY, 'W_up', `[${p.dModel},${p.dFf}]`);
    arrowDown(grp, cx, hBot, wuY - WEIGHT_H/2, c.stroke);
    const uoY = wuY + WEIGHT_H/2 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, uoY, 'up', `[${p.seqLen},${p.dFf}]`, c.fill, c.stroke);
    arrowDown(grp, cx, wuY + WEIGHT_H/2, uoY - MAT_H/2, c.stroke);
    drawShapeEq(grp, cx, uoY + MAT_H/2 + 20, `x [${p.seqLen},${p.dModel}]·W_up → up [${p.seqLen},${p.dFf}]`, c.stroke);
    colY[0] = uoY + MAT_H/2 + 40;
  }
  // MoE FFN (col 1)
  {
    const cx = COL_CX[1]; const c = COLORS.decoder;
    const grp = startGroup(g, 'step-moe-rt', stepId);
    const hBot = stepHeader(grp, cx, colY[1], stepId, 'Router', 'gate = softmax(x·W_r)', c.fill, c.stroke);
    arrowDown(grp, cx, colY[1], hBot, c.stroke);
    const wrY = hBot + BOX_TO_ROW + 36;
    drawWeight(grp, cx, wrY, 'W_router', `[${p.dModel},4]`, c.fill, c.stroke, 90, 68);
    arrowDown(grp, cx, hBot, wrY - 34, c.stroke);
    const gtY = wrY + 34 + ROW_EQ + VEC_H/2;
    drawSmVec(grp, cx, gtY, 'gate', `[${p.seqLen},4]`, c.fill, c.stroke, 110);
    arrowDown(grp, cx, wrY + 34, gtY - VEC_H/2, c.stroke);
    lbl(grp, cx, gtY + VEC_H/2 + 12, 'route to top-k experts', { size: 8.5, color: COLORS.muted });
    drawShapeEq(grp, cx, gtY + VEC_H/2 + 28, `x·W_r [${p.dModel},4] → softmax → gate`, c.stroke);
    colY[1] = gtY + VEC_H/2 + 48;
  }
  // Seq2Seq FFN (col 2)
  {
    const cx = COL_CX[2]; const c = COLORS.seq2seq;
    const grp = startGroup(g, 'step-s2s-up', stepId);
    const hBot = stepHeader(grp, cx, colY[2], stepId, 'Up Projection', 'up = x·W_up', c.fill, c.stroke);
    arrowDown(grp, cx, colY[2], hBot, c.stroke);
    const wuY = hBot + BOX_TO_ROW + WEIGHT_H/2;
    drawWeight(grp, cx, wuY, 'W_up', `[${p.dModel},${p.dFf}]`);
    arrowDown(grp, cx, hBot, wuY - WEIGHT_H/2, c.stroke);
    const uoY = wuY + WEIGHT_H/2 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, uoY, 'up', `[${p.seqLen},${p.dFf}]`, c.fill, c.stroke);
    arrowDown(grp, cx, wuY + WEIGHT_H/2, uoY - MAT_H/2, c.stroke);
    drawShapeEq(grp, cx, uoY + MAT_H/2 + 20, `x [${p.seqLen},${p.dModel}]·W_up → up [${p.seqLen},${p.dFf}]`, c.stroke);
    colY[2] = uoY + MAT_H/2 + 40;
  }
  steps.push(makeStep(stepId, 'Up/Router', 'Up-Projection / Router', 'up = x·W_up / gate = router(x)', 'Dense FFN up-projects; MoE routes tokens to experts.', 'step-ffn-up', COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 3: Activation / Experts ──
  // Dense: GELU; MoE: Expert 0 + Expert 1; Seq2Seq: GELU
  {
    const cx = COL_CX[0]; const c = COLORS.encoder;
    const grp = startGroup(g, 'step-ffn-act', stepId);
    const hBot = stepHeader(grp, cx, colY[0], stepId, 'Activation', 'h = GELU(up)', c.fill, c.stroke);
    arrowDown(grp, cx, colY[0], hBot, c.stroke);
    const actY = hBot + BOX_TO_ROW + 16;
    drawBadge(grp, cx, actY, 'GELU', c.fill, c.stroke);
    arrowDown(grp, cx, hBot, actY - 16, c.stroke);
    const hoY = actY + 16 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, hoY, 'h', `[${p.seqLen},${p.dFf}]`, c.fill, c.stroke);
    arrowDown(grp, cx, actY + 16, hoY - MAT_H/2, c.stroke);
    colY[0] = hoY + MAT_H/2 + 28;
  }
  // MoE: Experts
  {
    const cx = COL_CX[1]; const c = COLORS.decoder;
    const grp = startGroup(g, 'step-moe-experts', stepId);
    const hBot = stepHeader(grp, cx, colY[1], stepId, 'Experts', 'e_i = GELU(x·W_i)', c.fill, c.stroke);
    arrowDown(grp, cx, colY[1], hBot, c.stroke);
    const e0cx = cx - 85; const e1cx = cx + 85;
    const eHdrY = hBot + BOX_TO_ROW;
    // Expert 0
    drawBadge(grp, e0cx, eHdrY + 16, 'Expert 0', c.fill, c.stroke);
    const e0wY = eHdrY + 16 + ROW_EQ + SM_H/2;
    drawSmWeight(grp, e0cx, e0wY, 'W_0', `[${p.dModel},${Math.floor(p.dFf/2)}]`, c.fill, c.stroke);
    arrowDown(grp, e0cx, eHdrY + 32, e0wY - SM_H/2, c.stroke);
    const e0oY = e0wY + SM_H/2 + ROW_EQ/2 + VEC_H/2;
    drawSmVec(grp, e0cx, e0oY, 'e0', `[${p.seqLen},${Math.floor(p.dFf/2)}]`, c.fill, c.stroke, 84);
    arrowDown(grp, e0cx, e0wY + SM_H/2, e0oY - VEC_H/2, c.stroke);
    // Expert 1
    drawBadge(grp, e1cx, eHdrY + 16, 'Expert 1', c.fill, c.stroke);
    const e1wY = eHdrY + 16 + ROW_EQ + SM_H/2;
    drawSmWeight(grp, e1cx, e1wY, 'W_1', `[${p.dModel},${Math.floor(p.dFf/2)}]`, c.fill, c.stroke);
    arrowDown(grp, e1cx, eHdrY + 32, e1wY - SM_H/2, c.stroke);
    const e1oY = e1wY + SM_H/2 + ROW_EQ/2 + VEC_H/2;
    drawSmVec(grp, e1cx, e1oY, 'e1', `[${p.seqLen},${Math.floor(p.dFf/2)}]`, c.fill, c.stroke, 84);
    arrowDown(grp, e1cx, e1wY + SM_H/2, e1oY - VEC_H/2, c.stroke);
    colY[1] = Math.max(e0oY, e1oY) + VEC_H/2 + 28;
  }
  // Seq2Seq: GELU
  {
    const cx = COL_CX[2]; const c = COLORS.seq2seq;
    const grp = startGroup(g, 'step-s2s-act', stepId);
    const hBot = stepHeader(grp, cx, colY[2], stepId, 'Activation', 'h = GELU(up)', c.fill, c.stroke);
    arrowDown(grp, cx, colY[2], hBot, c.stroke);
    const actY = hBot + BOX_TO_ROW + 16;
    drawBadge(grp, cx, actY, 'GELU', c.fill, c.stroke);
    arrowDown(grp, cx, hBot, actY - 16, c.stroke);
    const hoY = actY + 16 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, hoY, 'h', `[${p.seqLen},${p.dFf}]`, c.fill, c.stroke);
    arrowDown(grp, cx, actY + 16, hoY - MAT_H/2, c.stroke);
    colY[2] = hoY + MAT_H/2 + 28;
  }
  steps.push(makeStep(stepId, 'Act/Experts', 'Activation / Expert Computation', 'h = GELU(up) / e_i = GELU(x·W_i)', 'GELU activation for dense; per-expert computation for MoE.', 'step-ffn-act', COLORS.decoder.stroke, COLORS.decoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 4: Down Projection / Gate ──
  // Dense: W_down
  {
    const cx = COL_CX[0]; const c = COLORS.encoder;
    const grp = startGroup(g, 'step-ffn-dn', stepId);
    const hBot = stepHeader(grp, cx, colY[0], stepId, 'Down Projection', 'out = h·W_dn', c.fill, c.stroke);
    arrowDown(grp, cx, colY[0], hBot, c.stroke);
    const wdY = hBot + BOX_TO_ROW + WEIGHT_H/2;
    drawWeight(grp, cx, wdY, 'W_down', `[${p.dFf},${p.dModel}]`);
    arrowDown(grp, cx, hBot, wdY - WEIGHT_H/2, c.stroke);
    const foY = wdY + WEIGHT_H/2 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, foY, 'ffn_out', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, wdY + WEIGHT_H/2, foY - MAT_H/2, c.stroke);
    drawShapeEq(grp, cx, foY + MAT_H/2 + 20, `h [${p.seqLen},${p.dFf}]·W_down → [${p.seqLen},${p.dModel}]`, c.stroke);
    colY[0] = foY + MAT_H/2 + 40;
  }
  // MoE: Gate & Combine
  {
    const cx = COL_CX[1]; const c = COLORS.decoder;
    const grp = startGroup(g, 'step-moe-gate', stepId);
    const hBot = stepHeader(grp, cx, colY[1], stepId, 'Gate & Combine', 'out = gate⊙experts', c.fill, c.stroke);
    arrowDown(grp, cx, colY[1], hBot, c.stroke);
    const gbY = hBot + BOX_TO_ROW + 16;
    drawBadge(grp, cx, gbY, 'gate ⊙ stack(e0,e1)', c.fill, c.stroke);
    arrowDown(grp, cx, hBot, gbY - 16, c.stroke);
    const moY = gbY + 16 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, moY, 'moe_out', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, gbY + 16, moY - MAT_H/2, c.stroke);
    drawShapeEq(grp, cx, moY + MAT_H/2 + 20, `gate⊙stack(e0,e1) → W_down → [${p.seqLen},${p.dModel}]`, c.stroke);
    colY[1] = moY + MAT_H/2 + 40;
  }
  // Seq2Seq: W_down
  {
    const cx = COL_CX[2]; const c = COLORS.seq2seq;
    const grp = startGroup(g, 'step-s2s-dn', stepId);
    const hBot = stepHeader(grp, cx, colY[2], stepId, 'Down Projection', 'out = h·W_dn', c.fill, c.stroke);
    arrowDown(grp, cx, colY[2], hBot, c.stroke);
    const wdY = hBot + BOX_TO_ROW + WEIGHT_H/2;
    drawWeight(grp, cx, wdY, 'W_down', `[${p.dFf},${p.dModel}]`);
    arrowDown(grp, cx, hBot, wdY - WEIGHT_H/2, c.stroke);
    const foY = wdY + WEIGHT_H/2 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, foY, 's2s_out', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, wdY + WEIGHT_H/2, foY - MAT_H/2, c.stroke);
    drawShapeEq(grp, cx, foY + MAT_H/2 + 20, `h [${p.seqLen},${p.dFf}]·W_down → [${p.seqLen},${p.dModel}]`, c.stroke);
    colY[2] = foY + MAT_H/2 + 40;
  }
  steps.push(makeStep(stepId, 'Down/Gate', 'Down-Projection / Gating', 'out = h·W_down / gate⊙experts', 'Down-project back to d_model or gate-combine expert outputs.', 'step-ffn-dn', COLORS.seq2seq.stroke, COLORS.seq2seq.fill));
  y = Math.max(...colY) + GROUP_GAP;

  y = drawCompTable(g, CX, y,
    [['Property','Dense FFN','MoE FFN','Seq2Seq FFN'],
     ['Params','2×D×D_ff','2×D×D_ff/n + router','2×D×D_ff'],
     ['Activation','GELU','SiLU (per-expert)','GELU'],
     ['Routing','None','Top-k gate','None'],
     ['Capacity','Fixed','Per-expert','Fixed'],
     ['Example','Standard TFM','Mixtral, DeepSeek','T5, BART']],
    ['#666', COLORS.encoder.stroke, COLORS.decoder.stroke, COLORS.seq2seq.stroke]) + 24;

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Training variant — row-based rendering
// ═══════════════════════════════════════════════════════════════════════════════

function renderTraining(g: Gsel, startY: number, p: ArchParams): { steps: ArchStep[]; y: number } {
  const steps: ArchStep[] = [];
  let stepId = 1;
  let y = startY;
  const types = [
    { name: 'Encoder', model: 'BERT-style', color: COLORS.encoder },
    { name: 'Decoder', model: 'GPT-style', color: COLORS.decoder },
    { name: 'Seq2Seq', model: 'T5-style', color: COLORS.seq2seq },
  ];

  // Step 1: Shared input
  const gIn = startGroup(g, 'step-tr-in', stepId);
  drawSeqMatrix(gIn, CX, y, 'x', `[${p.seqLen},${p.dModel}]`, COLORS.encoder.fill, COLORS.encoder.stroke);
  lbl(gIn, CX, y + MAT_H/2 + 18, 'shared input', { size: 9.5, color: COLORS.muted });
  steps.push(makeStep(stepId, 'Input', 'Input', `x: [${p.seqLen}, ${p.dModel}]`, 'Shared input for training comparison.', 'step-tr-in', COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++; y += MAT_H/2 + 48;

  forkArrows(g, y); y += 24;
  types.forEach((t, ci) => drawColHeader(g, COL_CX[ci], y, t.name, t.model, '', t.color));
  y += COL_HDR_H + 16;

  const colY = [y, y, y];

  // ── Step 2: Scale ──
  // Encoder & Decoder have scale; Seq2Seq has Linear Enc
  // Col 0: Encoder Scale
  {
    const cx = COL_CX[0]; const c = COLORS.encoder;
    const grp = startGroup(g, 'step-tr-sc', stepId);
    const hBot = stepHeader(grp, cx, colY[0], stepId, 'Scale', 'x = x/√d', c.fill, c.stroke);
    arrowDown(grp, cx, colY[0], hBot, c.stroke);
    const scY = hBot + BOX_TO_ROW + 16;
    drawBadge(grp, cx, scY, '× 1/√d_k', c.fill, c.stroke);
    arrowDown(grp, cx, hBot, scY - 16, c.stroke);
    const scOutY = scY + 16 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, scOutY, 'x_scaled', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, scY + 16, scOutY - MAT_H/2, c.stroke);
    colY[0] = scOutY + MAT_H/2 + 28;
  }
  // Col 1: Decoder Scale
  {
    const cx = COL_CX[1]; const c = COLORS.decoder;
    const grp = startGroup(g, 'step-tr-sc', stepId);
    const hBot = stepHeader(grp, cx, colY[1], stepId, 'Scale', 'x = x/√d', c.fill, c.stroke);
    arrowDown(grp, cx, colY[1], hBot, c.stroke);
    const scY = hBot + BOX_TO_ROW + 16;
    drawBadge(grp, cx, scY, '× 1/√d_k', c.fill, c.stroke);
    arrowDown(grp, cx, hBot, scY - 16, c.stroke);
    const scOutY = scY + 16 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, scOutY, 'x_scaled', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, scY + 16, scOutY - MAT_H/2, c.stroke);
    colY[1] = scOutY + MAT_H/2 + 28;
  }
  // Col 2: Seq2Seq Linear Enc
  {
    const cx = COL_CX[2]; const c = COLORS.seq2seq;
    const grp = startGroup(g, 'step-tr-s2s-enc', stepId);
    const hBot = stepHeader(grp, cx, colY[2], stepId, 'Linear Enc', 'h = x·W_enc', c.fill, c.stroke);
    arrowDown(grp, cx, colY[2], hBot, c.stroke);
    const leY = hBot + BOX_TO_ROW + WEIGHT_H/2;
    drawWeight(grp, cx, leY, 'W_enc', `[${p.dModel},${p.dFf}]`);
    arrowDown(grp, cx, hBot, leY - WEIGHT_H/2, c.stroke);
    const loY = leY + WEIGHT_H/2 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, loY, 'h', `[${p.seqLen},${p.dFf}]`, c.fill, c.stroke);
    arrowDown(grp, cx, leY + WEIGHT_H/2, loY - MAT_H/2, c.stroke);
    colY[2] = loY + MAT_H/2 + 28;
  }
  steps.push(makeStep(stepId, 'Scale/Enc', 'Scale / Linear Encoding', 'x/√d_k or x·W_enc', 'Scale by 1/√d_k for stable gradients, or linear encode for seq2seq.', 'step-tr-sc', COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 3: Linear Up ──
  // Encoder & Decoder: W_up; Seq2Seq: Linear Dec (W_dec)
  [0, 1].forEach((ci) => {
    const cx = COL_CX[ci]; const c = types[ci].color;
    const grp = startGroup(g, 'step-tr-lu', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'Linear Up', 'h = x·W_up', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const luY = hBot + BOX_TO_ROW + WEIGHT_H/2;
    drawWeight(grp, cx, luY, 'W_up', `[${p.dModel},${p.dFf}]`);
    arrowDown(grp, cx, hBot, luY - WEIGHT_H/2, c.stroke);
    const loY = luY + WEIGHT_H/2 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, loY, 'h', `[${p.seqLen},${p.dFf}]`, c.fill, c.stroke);
    arrowDown(grp, cx, luY + WEIGHT_H/2, loY - MAT_H/2, c.stroke);
    colY[ci] = loY + MAT_H/2 + 28;
  });
  // Col 2: Seq2Seq Linear Dec
  {
    const cx = COL_CX[2]; const c = COLORS.seq2seq;
    const grp = startGroup(g, 'step-tr-s2s-dec', stepId);
    const hBot = stepHeader(grp, cx, colY[2], stepId, 'Linear Dec', 'out = h·W_dec', c.fill, c.stroke);
    arrowDown(grp, cx, colY[2], hBot, c.stroke);
    const ldY = hBot + BOX_TO_ROW + WEIGHT_H/2;
    drawWeight(grp, cx, ldY, 'W_dec', `[${p.dFf},${p.dModel}]`);
    arrowDown(grp, cx, hBot, ldY - WEIGHT_H/2, c.stroke);
    const doY = ldY + WEIGHT_H/2 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, doY, 's2s_out', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, ldY + WEIGHT_H/2, doY - MAT_H/2, c.stroke);
    colY[2] = doY + MAT_H/2 + 28;
  }
  steps.push(makeStep(stepId, 'Linear', 'Linear Layers', 'h = x·W_up / out = h·W_dec', 'Up-projection for encoder/decoder; decode for seq2seq.', 'step-tr-lu', COLORS.decoder.stroke, COLORS.decoder.fill));
  stepId++;
  y = Math.max(...colY) + GROUP_GAP;
  colY[0] = colY[1] = colY[2] = y;

  // ── Step 4: Linear Down + Dropout / (Seq2Seq done) ──
  [0, 1].forEach((ci) => {
    const cx = COL_CX[ci]; const c = types[ci].color;
    const grp = startGroup(g, 'step-tr-ld', stepId);
    const hBot = stepHeader(grp, cx, colY[ci], stepId, 'Linear Down + Drop', 'out = W_dn(h)', c.fill, c.stroke);
    arrowDown(grp, cx, colY[ci], hBot, c.stroke);
    const ldY = hBot + BOX_TO_ROW + WEIGHT_H/2;
    drawWeight(grp, cx, ldY, 'W_down', `[${p.dFf},${p.dModel}]`);
    arrowDown(grp, cx, hBot, ldY - WEIGHT_H/2, c.stroke);
    const dpY = ldY + WEIGHT_H/2 + ROW_EQ/2 + 16;
    drawBadge(grp, cx, dpY, 'dropout(0.1)', c.fill, c.stroke);
    arrowDown(grp, cx, ldY + WEIGHT_H/2, dpY - 16, c.stroke);
    const doY = dpY + 16 + ROW_EQ + MAT_H/2;
    drawSeqMatrix(grp, cx, doY, 'out', `[${p.seqLen},${p.dModel}]`, c.fill, c.stroke);
    arrowDown(grp, cx, dpY + 16, doY - MAT_H/2, c.stroke);
    colY[ci] = doY + MAT_H/2 + 28;
  });
  // Seq2Seq: just badge "done"
  {
    const cx = COL_CX[2]; const c = COLORS.seq2seq;
    const grp = startGroup(g, 'step-tr-s2s-done', stepId);
    const doneY = colY[2] + 16;
    drawBadge(grp, cx, doneY, 'output ready', c.fill, c.stroke);
    colY[2] = doneY + 24;
  }
  steps.push(makeStep(stepId, 'Down/Drop', 'Linear Down + Dropout', 'out = dropout(h·W_down, 0.1)', 'Down-project and apply dropout for regularization.', 'step-tr-ld', COLORS.seq2seq.stroke, COLORS.seq2seq.fill));
  y = Math.max(...colY) + GROUP_GAP;

  // Converge arrows to shared loss
  ARCHS.forEach((_, ci) => drawArrow(g as Sel, COL_CX[ci], y - GROUP_GAP, CX, y, { color: '#78909c' }));

  // ── Step 5: Cross-Entropy Loss ──
  const gL = startGroup(g, 'step-tr-loss', stepId);
  const lhBot = stepHeader(gL, CX, y, stepId, 'Cross-Entropy Loss', 'L = CE(h, target)', COLORS.loss.fill, COLORS.loss.stroke, 520);
  arrowDown(gL, CX, y - 4, lhBot, COLORS.loss.stroke);
  const lossY = lhBot + BOX_TO_ROW + VEC_H/2;
  drawSmVec(gL, CX - 130, lossY, 'enc_loss', `[1]`, COLORS.encoder.fill, COLORS.encoder.stroke, 110);
  drawSmVec(gL, CX, lossY, 'dec_loss', `[1]`, COLORS.decoder.fill, COLORS.decoder.stroke, 110);
  drawSmVec(gL, CX + 130, lossY, 's2s_loss', `[1]`, COLORS.seq2seq.fill, COLORS.seq2seq.stroke, 110);
  opCircle(gL, CX, lossY + VEC_H/2 + 32, '+', COLORS.loss.stroke);
  arrowDown(gL, CX - 130, lossY + VEC_H/2, lossY + VEC_H/2 + 16, COLORS.loss.stroke);
  arrowDown(gL, CX, lossY + VEC_H/2, lossY + VEC_H/2 + 16, COLORS.loss.stroke);
  arrowDown(gL, CX + 130, lossY + VEC_H/2, lossY + VEC_H/2 + 16, COLORS.loss.stroke);
  steps.push(makeStep(stepId, 'Loss', 'Cross-Entropy Loss', 'L = CE(h, target)', 'Per-architecture cross-entropy loss.', 'step-tr-loss', COLORS.loss.stroke, COLORS.loss.fill));
  stepId++;
  y = lossY + VEC_H/2 + 56;

  // ── Step 6: Total Loss & Perplexity ──
  const gP = startGroup(g, 'step-tr-ppl', stepId);
  const phBot = stepHeader(gP, CX, y, stepId, 'Total Loss & PPL', 'PPL = exp(L)', COLORS.loss.fill, COLORS.loss.stroke, 520);
  arrowDown(gP, CX, y - 4, phBot, COLORS.loss.stroke);
  const tlY = phBot + BOX_TO_ROW + VEC_H/2;
  drawSmVec(gP, CX, tlY, 'total_loss', `[1]`, COLORS.loss.fill, COLORS.loss.stroke, 130);
  arrowDown(gP, CX, phBot, tlY - VEC_H/2, COLORS.loss.stroke);
  const pplY = tlY + VEC_H/2 + ROW_EQ/2 + 16;
  drawBadge(gP, CX, pplY, 'exp()', COLORS.loss.fill, COLORS.loss.stroke);
  arrowDown(gP, CX, tlY + VEC_H/2, pplY - 16, COLORS.loss.stroke);
  const pplOutY = pplY + 16 + ROW_EQ + VEC_H/2;
  drawSmVec(gP, CX, pplOutY, 'PPL', `[1]`, COLORS.loss.fill, COLORS.loss.stroke, 110);
  arrowDown(gP, CX, pplY + 16, pplOutY - VEC_H/2, COLORS.loss.stroke);
  drawShapeEq(gP, CX, pplOutY + VEC_H/2 + 20, `total_loss = Σ losses → PPL = exp(total_loss)`, COLORS.loss.stroke);
  steps.push(makeStep(stepId, 'PPL', 'Perplexity', 'PPL = exp(L)', 'Perplexity = exp(cross-entropy loss).', 'step-tr-ppl', COLORS.loss.stroke, COLORS.loss.fill));
  y = pplOutY + VEC_H/2 + 40;

  y = drawCompTable(g, CX, y,
    [['Property','Encoder','Decoder','Seq2Seq'],
     ['Scaling','1/√d_k','1/√d_k','None'],
     ['Dropout','0.1','0.1','None'],
     ['Loss','CE (class)','CE (next-token)','CE (seq2seq)'],
     ['Metric','Accuracy','PPL','BLEU / ROUGE']],
    ['#666', COLORS.encoder.stroke, COLORS.decoder.stroke, COLORS.seq2seq.stroke]) + 24;

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main entry
// ═══════════════════════════════════════════════════════════════════════════════

export function renderArchitectureComparisonDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const dModel = Number(params.d_model) || 512;
  const seqLen = Number(params.seq_len) || 128;
  const dFf = Number(params.d_ff) || 2048;
  const variant = String(params.variant || 'overview');

  const p: ArchParams = { dModel, seqLen, dFf, variant };
  const root = g as unknown as Gsel;
  let y = 28;

  const variantLabel = variant === 'attention' ? 'Attention Choices'
    : variant === 'ffn_moe' ? 'FFN & MoE'
    : variant === 'training' ? 'Training & Scale'
    : 'Encoder-only vs Decoder-only vs Encoder-Decoder';

  lbl(root, CX, y, 'Transformer Architecture Comparison', { size: 18, weight: '700', color: COLORS.text });
  y += 22;
  lbl(root, CX, y, `${variantLabel} · d_model=${dModel} · seq_len=${seqLen} · d_ff=${dFf}`, { size: 11, color: COLORS.muted });
  y += 28;

  y = drawParamSummary(root, CX, y, p);
  y += 16;

  let result: { steps: ArchStep[]; y: number };
  if (variant === 'attention') result = renderAttention(root, y, p);
  else if (variant === 'ffn_moe') result = renderFfnMoe(root, y, p);
  else if (variant === 'training') result = renderTraining(root, y, p);
  else result = renderOverview(root, y, p);

  let footerY = result.y + 20;

  const insightText = variant === 'attention'
    ? 'Self-attention uses the same input for Q, K, V (bidirectional). Cross-attention takes Q from the decoder and K, V from the encoder. Causal attention masks future positions with a lower-triangular mask, enabling autoregressive generation.'
    : variant === 'ffn_moe'
    ? 'Dense FFN uses a single up/down projection pair for all tokens. MoE FFN routes tokens to specialized experts via a learned gate, increasing capacity without increasing per-token FLOPs. Seq2Seq FFN mirrors the dense structure for encoder-decoder models.'
    : variant === 'training'
    ? 'Training scales activations by 1/√d_k, applies linear transformations, and uses dropout for regularization. Cross-entropy loss measures prediction quality; perplexity = exp(loss) gives an intuitive measure of model uncertainty.'
    : 'Encoder-only models (BERT) use bidirectional attention for understanding. Decoder-only models (GPT, Llama) use causal masking for autoregressive generation and now dominate LLM research. Encoder-Decoder models (T5, BART) handle seq2seq tasks like translation.';

  const perfText = variant === 'attention'
    ? `Attention FLOPs: O(S² · D) = ${fmtNum(2 * seqLen * seqLen * dModel)} per head. QKV projection: O(S · D²) = ${fmtNum(2 * seqLen * dModel * dModel * 3)}.`
    : variant === 'ffn_moe'
    ? `Dense FFN params: ${fmtNum(2 * dModel * dFf)}. MoE with 4 experts: ${fmtNum(4 * 2 * dModel * dFf / 2)} + router ${fmtNum(dModel * 4)}. MoE increases capacity but uses sparse activation.`
    : variant === 'training'
    ? `Linear FLOPs: O(S · D · D_ff) = ${fmtNum(2 * seqLen * dModel * dFf * 2)} per layer. Dropout adds zero FLOPs. Cross-entropy: O(S · V).`
    : `Per-layer params: ${fmtNum(4 * dModel * dModel + 2 * dModel * dFf)}. FLOPs: ${fmtNum(2 * seqLen * dModel * dModel * 4 + 2 * seqLen * dModel * dFf * 2)}.`;

  footerY = drawExplanation(g, 80, footerY, W - 160, insightText, 'insight');
  footerY = drawExplanation(g, 80, footerY, W - 160, perfText, 'perf');
  footerY += 14;

  const codeLines = variant === 'attention' ? [
    '# Attention comparison',
    'scores = Q @ K.transpose(-2, -1) / math.sqrt(d_k)',
    "if causal: scores = scores.masked_fill(causal_mask, float('-inf'))",
    'weights = F.softmax(scores, dim=-1)',
    'output = weights @ V',
  ] : variant === 'ffn_moe' ? [
    '# FFN comparison',
    '# Dense FFN',
    'up = x @ W_up; h = F.gelu(up); out = h @ W_down',
    '# MoE FFN',
    'gate = F.softmax(x @ W_router, dim=-1)  # [S, n_experts]',
    'expert_outs = stack([gelu(x @ W_i) for i in top_k])  # [S, d_ff, k]',
    "out = (gate * expert_outs).sum(-1) @ W_down",
  ] : variant === 'training' ? [
    '# Training comparison',
    'x_scaled = x / math.sqrt(d_model)',
    'h = F.dropout(x_scaled @ W_up @ W_down, p=0.1)',
    'loss = F.cross_entropy(h, target)',
    'ppl = torch.exp(loss)',
  ] : [
    '# Architecture comparison',
    '# Encoder-only: full bidirectional attention',
    'attn_mask = None  # attend to all positions',
    '# Decoder-only: causal mask',
    'attn_mask = torch.tril(torch.ones(seq, seq))',
    '# Encoder-Decoder: cross-attention',
    'h_dec = cross_attn(q=h_dec, k=h_enc, v=h_enc)',
  ];

  footerY = drawCodeAnnotation(g, 80, footerY, W - 160, `Architecture Comparison — ${variantLabel}`, [], codeLines);

  return { width: W, height: footerY + 24, steps: result.steps };
}
